class Solution {
public:
    long long maxKelements(std::vector<int>& nums, int k) {
        std::priority_queue<int> pq(nums.begin(), nums.end());
        long long score = 0;
        for (int i = 0; i < k; ++i) {
            int x = pq.top();
            pq.pop();
            score += x;
            pq.push((x + 2) / 3);
        }
        return score;
    }
};

class Solution {
    public long maxKelements(int[] nums, int k) {
        java.util.PriorityQueue<Integer> pq = new java.util.PriorityQueue<>(java.util.Collections.reverseOrder());
        for (int x : nums) pq.offer(x);
        long score = 0;
        for (int i = 0; i < k; i++) {
            int x = pq.poll();
            score += x;
            pq.offer((x + 2) / 3);
        }
        return score;
    }
}

var maxKelements = function(nums, k) {
    class MaxHeap {
        constructor(arr) {
            this.data = arr.slice();
            for (let i = (this.data.length >> 1) - 1; i >= 0; i--) this.down(i);
        }
        push(val) {
            this.data.push(val);
            this.up(this.data.length - 1);
        }
        pop() {
            const top = this.data[0];
            const bottom = this.data.pop();
            if (this.data.length > 0) {
                this.data[0] = bottom;
                this.down(0);
            }
            return top;
        }
        up(i) {
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (this.data[i] > this.data[p]) {
                    [this.data[i], this.data[p]] = [this.data[p], this.data[i]];
                    i = p;
                } else break;
            }
        }
        down(i) {
            const len = this.data.length;
            while ((i << 1) + 1 < len) {
                let left = (i << 1) + 1, right = left + 1, best = i;
                if (left < len && this.data[left] > this.data[best]) best = left;
                if (right < len && this.data[right] > this.data[best]) best = right;
                if (best !== i) {
                    [this.data[i], this.data[best]] = [this.data[best], this.data[i]];
                    i = best;
                } else break;
            }
        }
    }

    const pq = new MaxHeap(nums);
    let score = 0;
    for (let i = 0; i < k; i++) {
        const x = pq.pop();
        score += x;
        pq.push(Math.floor((x + 2) / 3));
    }
    return score;
};
